interface __EventSourceMessage {
  event?: string | undefined;
  id?: string | undefined;
  data: string;
}

interface __EventSourceParser {
  feed(chunk: string): void;
  reset(options?: { consume?: boolean }): void;
}

function __createParser(callbacks: {
  onEvent?: (event: __EventSourceMessage) => void;
  onRetry?: (retry: number) => void;
  onComment?: (comment: string) => void;
  onError?: (error: Error) => void;
}): __EventSourceParser {
  const {
    onEvent = () => {},
    onError = () => {},
    onRetry = () => {},
    onComment,
  } = callbacks;
  let incompleteLine = "";
  let isFirstChunk = true;
  let id: string | undefined;
  let data = "";
  let eventType = "";

  function feed(newChunk: string) {
    const chunk = isFirstChunk
      ? newChunk.replace(/^\xEF\xBB\xBF/, "")
      : newChunk;
    const [complete, incomplete] = __splitLines(`${incompleteLine}${chunk}`);
    for (const line of complete) {
      parseLine(line);
    }
    incompleteLine = incomplete;
    isFirstChunk = false;
  }

  function parseLine(line: string) {
    if (line === "") {
      dispatchEvent();
      return;
    }
    if (line.startsWith(":")) {
      if (onComment) onComment(line.slice(line.startsWith(": ") ? 2 : 1));
      return;
    }
    const fieldSeparatorIndex = line.indexOf(":");
    if (fieldSeparatorIndex !== -1) {
      const field = line.slice(0, fieldSeparatorIndex);
      const offset = line[fieldSeparatorIndex + 1] === " " ? 2 : 1;
      const value = line.slice(fieldSeparatorIndex + offset);
      processField(field, value);
      return;
    }
    processField(line, "");
  }

  function processField(field: string, value: string) {
    switch (field) {
      case "event":
        eventType = value;
        break;
      case "data":
        data = `${data}${value}\n`;
        break;
      case "id":
        id = value.includes("\0") ? undefined : value;
        break;
      case "retry":
        if (/^\d+$/.test(value)) onRetry(parseInt(value, 10));
        break;
    }
  }

  function dispatchEvent() {
    if (data.length > 0) {
      onEvent({
        id,
        event: eventType || undefined,
        data: data.endsWith("\n") ? data.slice(0, -1) : data,
      });
    }
    id = undefined;
    data = "";
    eventType = "";
  }

  function reset(options: { consume?: boolean } = {}) {
    if (incompleteLine && options.consume) parseLine(incompleteLine);
    isFirstChunk = true;
    id = undefined;
    data = "";
    eventType = "";
    incompleteLine = "";
  }

  return { feed, reset };
}

function __splitLines(chunk: string): [Array<string>, string] {
  const lines: Array<string> = [];
  let incompleteLine = "";
  let searchIndex = 0;
  while (searchIndex < chunk.length) {
    const crIndex = chunk.indexOf("\r", searchIndex);
    const lfIndex = chunk.indexOf("\n", searchIndex);
    let lineEnd = -1;
    if (crIndex !== -1 && lfIndex !== -1) {
      lineEnd = Math.min(crIndex, lfIndex);
    } else if (crIndex !== -1) {
      if (crIndex === chunk.length - 1) lineEnd = -1;
      else lineEnd = crIndex;
    } else if (lfIndex !== -1) {
      lineEnd = lfIndex;
    }
    if (lineEnd === -1) {
      incompleteLine = chunk.slice(searchIndex);
      break;
    } else {
      lines.push(chunk.slice(searchIndex, lineEnd));
      searchIndex = lineEnd + 1;
      if (chunk[searchIndex - 1] === "\r" && chunk[searchIndex] === "\n")
        searchIndex++;
    }
  }
  return [lines, incompleteLine];
}

class __EventSourceParserStream extends TransformStream<
  string,
  __EventSourceMessage
> {
  constructor() {
    let parser!: __EventSourceParser;
    super({
      start(controller) {
        parser = __createParser({
          onEvent: (event) => {
            controller.enqueue(event);
          },
        });
      },
      transform(chunk) {
        parser.feed(chunk);
      },
      // SSE events are terminated by a blank line. If the upstream
      // closes after the final `data:` line without a trailing
      // separator, the parser still has that event buffered — feed
      // the terminator on stream close so it gets dispatched
      // instead of silently dropped.
      flush() {
        parser.feed("\n\n");
      },
    });
  }
}

